import common from './locales/en/common.json';
import auth from './locales/en/auth.json';
import hr from './locales/en/hr.json';
import attendance from './locales/en/attendance.json';
export type Language = 'en' | 'ar';
export type Direction = 'ltr' | 'rtl';
export type TranslationKey = keyof typeof common | keyof typeof auth | keyof typeof hr | keyof typeof attendance;
export type TranslationOptions = { count?: number; [name: string]: unknown };
export function t(key: TranslationKey, options?: TranslationOptions): string;
export function getLanguage(): Language;
export function getDirection(): Direction;
export function normalizeLanguage(value: unknown): Language | null;
export function resolveLanguage(preference: unknown, deviceLocales?: Array<string | { languageTag?: string; languageCode?: string }>): Language;
export function hydrateLocale(): Promise<Language>;
export function setLanguage(language: Language | string): Promise<Language>;
export function useTranslation(): { t: typeof t; language: Language; isRTL: boolean; direction: Direction };
export function translateMessage(value: unknown, fallback?: TranslationKey): unknown;
export function isolateBidi(value: unknown): string;
export function getFormattingLocale(): string;
export function formatDate(value: Date | string | number, options?: Intl.DateTimeFormatOptions): string;
export function formatTime(value: Date | string | number, options?: Intl.DateTimeFormatOptions): string;
export function formatNumber(value: number | string, options?: Intl.NumberFormatOptions): string;
export function formatCurrency(value: number | string, currency?: string, options?: Intl.NumberFormatOptions): string;
export function formatDuration(seconds: number): string;
export function formatRelativeTime(value: number, unit?: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
export function formatList(values: string[], options?: Intl.ListFormatOptions): string;
